if ~exist('src400','var')
    src400 = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align.sqw');
end
if ~exist('src400sym','var')
    src400sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw ');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);liny; lz 0 2;keep_figure; %[output:0823464a]
w2_000b = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 2; keep_figure; %[output:171c725a]

%[output:88164110] %[output:7fe5f879]
hc.log_level = ll;

othrEi400cut110 = {[-0.1,0.1],[-0.1,0.1],[0,2,260]};
file = src400sym.full_filename %[output:4c828ed2]
[~,fname] = fileparts(file);

% recover masks not to draw them again
[cuts2fit400NG,masks_file]  = recover_selected_cuts('cuts2fit400NG','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[NG_FFCutsFits,allJfitfile] = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
%%


%%
hc.log_level = -2;
e0=150;
w2_001 = cut(src400sym,line_proj('offset',[0,0,0]),0.04,0.04,[-0.1,0.1],[e0-10,e0+10]);
plot(w2_001);lz 0 0.4; liny; keep_figure; %[output:38d4389e]

w2_00 = cut(src400sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; %[output:62e37844]
keep_figure; %[output:62e37844]

hc.log_level = ll;
%[output:216642d5]
%%
% <200> and <110> cuts along min FF change line
lpm110of110 = line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]);
w2_400NG = cut(src400sym,lpm110of110,[-1,0.02,1],othrEi400cut110{:});
plot(w2_400NG);lz 0 1; keep_figure %[output:581873c3]

fh = plot(w2_400NG); liny; lz 0 4; %[output:1a5868f9]
[w2_400NGfit,cuts2fit400NG] = draw_masks_helper(fh,cuts2fit400NG,'msk110_dirM110',3);
plot(w2_400NGfit); lz 0 1; keep_figure; %[output:1a5868f9]

cuts2fit400NG.all_cff_cuts = {w2_400NGfit};
%%
save(masks_file,'cuts2fit400NG','-v7.3');
%%
% <110> min FF change cut

w2_400NGfits = cut(w2_400NGfit,[0,0.005,0.5],[10,2,175],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(w2_400NGfits);lz 0 1; keep_figure; %[output:778c9548]

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGminFF',w2_400NGfits);

%%
% specialized <200> cut with min FF change
lpm110of200 = line_proj([-1,1,0],[1,1,0],'offset',[2,0,0]);
w2_400NGOff200 = cut(w2_400NGfit,lpm110of200,[0,0.005,0.5],othrEi400cut110{:},SymopReflection('normvec',[1,-1,0],'offset',[1,1,0]));
plot(w2_400NGOff200);lz 0 1; %[output:8093ddc7]

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off200NGminFF',w2_400NGOff200);
%%
% <110> cut with max FF change
lp110of110 = line_proj([1,1,0],[1,-1,0],'offset',[1,1,0]);
w2_400NGoff110maxFF = cut(src400sym,lp110of110,[-1,0.02,3],othrEi400cut110{:});
fh = plot(w2_400NGoff110maxFF); liny; lz 0 1; %[output:25a67e11]
[w2_400NGoff110maxFF,cuts2fit400NG] = draw_masks_helper(fh, ... %[output:25a67e11]
    cuts2fit400NG, 'msk110_dir110',3); %[output:25a67e11]
plot(w2_400NGoff110maxFF); lz 0 1; keep_figure; %[output:25a67e11]
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGmaxFF',cut(w2_400NGoff110maxFF,[0,0.005,0.5],[10,2,200]));
%%
% <200> cut with max FF change
lp110of200 = line_proj([1,1,0],[1,-1,0],'offset',[2,0,0]);
w2_400NGoff200maxFF = cut(src400sym,lp110of200,[-1,0.02,3],othrEi400cut110{:});
fh = plot(w2_400NGoff200maxFF); liny; lz 0 1; %[output:78107351]
[w2_400NGoff200maxFF,cuts2fit400NG] = draw_masks_helper(fh, ... %[output:78107351]
    cuts2fit400NG, 'msk200_dir110',3); %[output:78107351]
plot(w2_400NGoff200maxFF); lz 0 1; keep_figure; %[output:78107351]

lp110of020 = line_proj([1,1,0],[1,-1,0],'offset',[0,2,0]);
w2_400NGoff020maxFF = cut(src400sym,lp110of020,[-1,0.02,3],othrEi400cut110{:});
fh = plot(w2_400NGoff020maxFF); liny; lz 0 1; %[output:5ea68899]
[w2_400NGoff020maxFF,cuts2fit400NG] = draw_masks_helper(fh, ... %[output:5ea68899]
    cuts2fit400NG, 'msk020_dir110',3); %[output:5ea68899]
plot(w2_400NGoff020maxFF); lz 0 1; keep_figure; %[output:5ea68899]

w2ei400NGoff200maxFF = sqw_op_bin_pixels({w2_400NGoff200maxFF,w2_400NGoff020maxFF}, ...
    @move_all_to_proj, ...
    {[lp110of200,lp110of020]}, ...
    lp110of200,[0,0.005,0.5],othrEi400cut110{:},'-combine');
plot(w2ei400NGoff200maxFF);liny; lz 0 1;keep_figure; %[output:67b7bcbd]

%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei400_off110NGmaxFF',cut(w2ei400NGoff200maxFF,[0,0.005,0.5],[10,2,250]));

%%
if ~exist('mi','var')
    mi = MagneticIons();
end
w2nbgc = mi.correct_mag_ff(w2nbg);
plot(w2nbgc); lz 0 1;keep_figure;
%%
 w2s1 = symmetrise_sqw(w2nbgc,SymopReflection('norm',[-1,1,0],'offset',[0,0,0]))
 plot(w2s1); lz 0 1;keep_figure;
%%
w2s1 = cut(w2s1,[0,0.01,2],[]);
w2s2 = symmetrise_sqw(w2s1,SymopReflection('norm',[1,-1,0],'offset',[0,2,0]))
plot(w2s2); lz 0 1;keep_figure;
%%
w2s3 = symmetrise_sqw(w2s2,SymopReflection('norm',[-1,1,0],'offset',[0.5,1.5,0]))
w2s3.data.axes.title = "Ei800, one dir; bg removed; ff corrected"
plot(w2s3); lz 0 1;keep_figure;

